solution.sanitized:
def job_state(events):
    state = "new"
    transitions = {("new", "start"): "running", ("running", "finish"): "done", ("running", "fail"): "failed"}
    for event in events:
        key = state, event
        if key not in transitions:
            raise ValueError("invalid transition")
        state = transitions[key]
    return state

